import { useState, useEffect } from 'react';
import { fetchHealth, refreshStocks } from '../api/stockApi';

export default function Header() {
  const [health, setHealth] = useState(null);
  const [refreshing, setRefreshing] = useState(false);
  const [now, setNow] = useState(new Date());

  useEffect(() => {
    fetchHealth().then(setHealth).catch(() => {});
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const handleRefresh = async () => {
    setRefreshing(true);
    try {
      await refreshStocks();
      setTimeout(() => { setRefreshing(false); window.location.reload(); }, 3000);
    } catch {
      setRefreshing(false);
    }
  };

  const timeStr = now.toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  const dateStr = now.toLocaleDateString('ko-KR', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'short' });

  return (
    <header className="relative z-10 border-b border-[var(--border)]">
      <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
        {/* 로고 */}
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)] flex items-center justify-center">
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
              <polyline points="1,12 5,7 9,10 15,3" stroke="#0a0e1a" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
          <div>
            <h1 className="font-display text-2xl text-white tracking-widest leading-none">STOCKPULSE</h1>
            <p className="text-[10px] text-[var(--accent)] font-mono tracking-[0.2em] opacity-70">실시간 급상승 종목 AI 분석</p>
          </div>
        </div>

        {/* 중앙: 시간 + 업데이트 안내 */}
        <div className="hidden md:flex flex-col items-center">
          <span className="font-mono text-2xl text-white tracking-widest">{timeStr}</span>
          <span className="text-xs text-slate-400 mt-1">{dateStr}</span>
          <span className="text-[10px] font-mono mt-1 px-2 py-0.5 rounded-full border border-[var(--border)] text-slate-500">
            🕐 매시 정각 자동 업데이트 (평일 9~16시)
          </span>
        </div>

        {/* 우측: 상태 + 갱신 버튼 */}
        <div className="flex items-center gap-4">
          {health && (
            <div className="hidden sm:flex items-center gap-3 text-xs font-mono text-slate-400">
              <span className="flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-[var(--green)] animate-pulse" />
                종목 {health.stockCount}
              </span>
              <span>|</span>
              <span>뉴스 {health.newsCount}</span>
            </div>
          )}
          <button
            onClick={handleRefresh}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2 rounded-lg border border-[var(--accent)] text-[var(--accent)] text-sm font-mono
              hover:bg-[var(--accent)] hover:text-[var(--bg)] transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <svg className={`w-3.5 h-3.5 ${refreshing ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
            </svg>
            {refreshing ? '갱신중...' : '새로고침'}
          </button>
        </div>
      </div>
    </header>
  );
}
